export const MVP_CONCEPT_SCOPE = ["SAFETY", "SELF_CARE", "COMM"] as const;

export const MVP_COMPETENCY_FAMILIES: CompetencyFamily[] = FULL_COMPETENCY_FAMILIES.filter((family) => MVP_CONCEPT_SCOPE.includes(family.conceptId as typeof MVP_CONCEPT_SCOPE[number]));

export const MVP_COMPETENCIES: FunctionalCompetency[] = FULL_COMPETENCIES.filter((competency) => MVP_CONCEPT_SCOPE.includes(competency.conceptId as typeof MVP_CONCEPT_SCOPE[number]));

const MVP_COMPETENCY_IDS = new Set(MVP_COMPETENCIES.map((competency) => competency.competencyId));

export const MVP_COMPETENCY_COMPONENTS: CompetencyComponent[] = FULL_COMPETENCY_COMPONENTS.filter((component) => MVP_COMPETENCY_IDS.has(component.competencyId));

export const MVP_COMPONENT_RELATIONS: ComponentRelation[] = FULL_COMPONENT_RELATIONS.filter((relation) => MVP_COMPETENCY_IDS.has(relation.fromId) || MVP_COMPETENCY_IDS.has(relation.toId));

export const MVP_CURRICULUM_LINKS: CurriculumComponentLink[] = FULL_CURRICULUM_LINKS.filter((link) => MVP_COMPETENCY_IDS.has(link.competencyId));

export const MVP_ROLE_TASK_REQUIREMENTS: RoleTaskRequirement[] = FULL_ROLE_TASK_REQUIREMENTS.filter((task) => task.requiredCompetencyIds.some((competencyId) => MVP_COMPETENCY_IDS.has(competencyId)));
